-- These are the source-level queries generated by the mediator's GAV mappings.

-- Manufacturer DB: physical ProductCode is exposed as the global ItemCode by the view.
SELECT mp.ProductCode AS ItemCode,
       mp.ProductName,
       mc.legal_name AS Manufacturer,
       mp.BatchNo,
       mp.MfgDate AS ManufactureDate,
       mp.ExpiryDate
FROM manufactured_product mp
JOIN manufacturer_company mc ON mc.manufacturer_id = mp.manufacturer_id
WHERE mp.ProductCode = 'MED1001';

-- Distributor DB: SKU -> ItemCode
SELECT s.SKU AS ItemCode,
       sp.supplier_name AS Distributor,
       s.VendorName AS Vendor,
       s.DispatchDate,
       s.Quantity
FROM shipment s
JOIN supplier sp ON sp.supplier_id = s.supplier_id
WHERE s.SKU = 'MED1001';

-- Retailer DB: Barcode -> ItemCode
SELECT sr.Barcode AS ItemCode,
       rs.store_name AS Retailer,
       rs.city AS RetailCity,
       sr.PurchaseDate,
       sr.SalePrice
FROM sale_record sr
JOIN retail_store rs ON rs.store_id = sr.store_id
WHERE sr.Barcode = 'MED1001';

-- Item Scan DB: ItemUniqueCode -> ItemCode
SELECT ItemUniqueCode AS ItemCode,
       ScannedName,
       ScanTimestamp,
       ScanLocation
FROM item_scan
WHERE ItemUniqueCode = 'MED1001';

-- Authority DB: ReportedCode -> ItemCode
SELECT ReportedCode AS ItemCode,
       ComplaintType,
       ReportDate,
       MinistryStatus,
       CaseReference,
       EvidenceNote
FROM consumer_report
WHERE ReportedCode = 'MED1001';
